(()=>{const $=id=>document.getElementById(id),n=id=>parseFloat($(id).value);function target(p,max,rest,method){return method==='hrr'?rest+(max-rest)*p:max*p}function go(){const age=n('age'),rest=n('rest'),method=$('method').value;if(!Number.isFinite(age)||age<10||age>100||!Number.isFinite(rest)||rest<20||rest>=220-age){$('note').textContent='Enter a plausible age and a resting heart rate below the age-predicted maximum.';$('note').className='helper danger';return;}const max=220-age;$('max').textContent=Math.round(max)+' bpm';const range=(a,b)=>Math.round(target(a,max,rest,method))+'–'+Math.round(target(b,max,rest,method))+' bpm';$('moderate').textContent=range(.5,.7);$('vigorous').textContent=range(.7,.85);const bands=[[.5,.6,'Zone 1'],[.6,.7,'Zone 2'],[.7,.8,'Zone 3'],[.8,.9,'Zone 4'],[.9,1,'Zone 5']];$('zones').innerHTML=bands.map(x=>'<tr><td>'+x[2]+'</td><td>'+Math.round(x[0]*100)+'–'+Math.round(x[1]*100)+'%</td><td>'+range(x[0],x[1])+'</td></tr>').join('');$('note').textContent='Age-predicted maximum heart rate is an average estimate. Medications, cardiovascular conditions and individual physiology can change appropriate exercise heart rates.';$('note').className='helper';}
['age','rest','method'].forEach(id=>$(id).addEventListener('input',go));$('calc').onclick=go;$('reset').onclick=()=>{$('age').value=35;$('rest').value=60;$('method').value='max';go();};go();})();
</script>
